static long countInv(int[] a, int[] aux, int lo, int hi) {
    if (lo >= hi) return 0;
    int mid = (lo + hi) / 2;
    long c = countInv(a, aux, lo, mid) + countInv(a, aux, mid + 1, hi);
    for (int k = lo; k <= hi; k++) aux[k] = a[k];
    int i = lo, j = mid + 1;
    for (int k = lo; k <= hi; k++) {
        if (i > mid) a[k] = aux[j++];
        else if (j > hi) a[k] = aux[i++];
        else if (aux[j] < aux[i]) { a[k] = aux[j++]; c += mid - i + 1; }
        else a[k] = aux[i++];
    }
    return c;
}
